-- ===========================================================================
--  V1__init.sql  -  core schema for diagnostic test bookings and payments
--
--  Design notes
--  ------------
--  * Primary keys are UUIDs generated by the application (Hibernate), not by
--    the database. IDs that appear in URLs are therefore not guessable, which
--    is one reason we can safely answer 404 (not 403) for another user's
--    booking without leaking its existence.
--  * Every timestamp is TIMESTAMPTZ, so the value is stored with its offset and
--    always comes back as an absolute point in time. The app writes UTC.
--  * Money is always NUMERIC(10, 2). Floating point cannot represent 0.10
--    exactly, so money never uses double / REAL / FLOAT.
--  * Enum-ish columns are VARCHAR plus a CHECK constraint. The constraint makes
--    an illegal value impossible even if some other tool writes to the table,
--    while VARCHAR keeps the values readable in psql.
--  * "updated_at" is maintained by the JPA layer (@PrePersist / @PreUpdate).
--    The DEFAULT here is only a safety net for rows inserted outside the app.
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- users
-- ---------------------------------------------------------------------------
CREATE TABLE users (
    id            UUID         PRIMARY KEY,
    name          VARCHAR(120) NOT NULL,
    email         VARCHAR(255) NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    role          VARCHAR(20)  NOT NULL DEFAULT 'USER',
    created_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),

    -- One account per email address. Without this a user could sign up twice.
    CONSTRAINT uq_users_email UNIQUE (email),

    -- Signup lowercases the email before saving, and this constraint makes sure
    -- nobody slips an upper-case address in later: Ada@x.com and ada@x.com would
    -- otherwise be two separate UNIQUE rows but the same real mailbox.
    CONSTRAINT ck_users_email_is_lowercase CHECK (email = lower(email)),

    CONSTRAINT ck_users_role CHECK (role IN ('USER', 'ADMIN'))
);

-- ---------------------------------------------------------------------------
-- diagnostic_centres
-- ---------------------------------------------------------------------------
CREATE TABLE diagnostic_centres (
    id         UUID         PRIMARY KEY,
    name       VARCHAR(160) NOT NULL,
    city       VARCHAR(80)  NOT NULL,
    address    VARCHAR(255),
    created_at TIMESTAMPTZ  NOT NULL DEFAULT now()
);

-- GET /centres?city=Bengaluru always filters on city. V3 replaces this with an
-- expression index on lower(city), which is what the query actually needs.
CREATE INDEX idx_diagnostic_centres_city ON diagnostic_centres (city);

-- ---------------------------------------------------------------------------
-- diagnostic_tests  (the test catalogue, e.g. "Lipid Profile")
-- ---------------------------------------------------------------------------
CREATE TABLE diagnostic_tests (
    id          UUID         PRIMARY KEY,
    name        VARCHAR(160) NOT NULL,
    description VARCHAR(500),

    -- Two catalogue entries with the same name would be confusing and would
    -- make ?name= search ambiguous.
    CONSTRAINT uq_diagnostic_tests_name UNIQUE (name)
);

-- ---------------------------------------------------------------------------
-- centre_tests  (join table: which centre offers which test, at which price)
--
-- This is a many-to-many relationship with a payload (price), so it is modelled
-- as its own table instead of a plain @ManyToMany, which cannot hold attributes.
-- ---------------------------------------------------------------------------
CREATE TABLE centre_tests (
    id        UUID          PRIMARY KEY,
    centre_id UUID          NOT NULL,
    test_id   UUID          NOT NULL,
    price     NUMERIC(10, 2) NOT NULL,

    CONSTRAINT fk_centre_tests_centre
        FOREIGN KEY (centre_id) REFERENCES diagnostic_centres (id) ON DELETE RESTRICT,
    CONSTRAINT fk_centre_tests_test
        FOREIGN KEY (test_id) REFERENCES diagnostic_tests (id) ON DELETE RESTRICT,

    -- A centre cannot offer the same test twice at two different prices.
    -- This unique key also serves every "tests of this centre" lookup, so no
    -- extra index is needed on centre_id.
    CONSTRAINT uq_centre_tests_centre_test UNIQUE (centre_id, test_id),

    -- Guards against a free or negative test slipping in through a bad request
    -- or a future admin endpoint.
    CONSTRAINT ck_centre_tests_price_positive CHECK (price > 0)
);

-- Postgres does NOT index the referencing side of a foreign key, and we look
-- tests up by test_id ("which centres offer this test?").
CREATE INDEX idx_centre_tests_test_id ON centre_tests (test_id);

-- ---------------------------------------------------------------------------
-- bookings
-- ---------------------------------------------------------------------------
CREATE TABLE bookings (
    id               UUID          PRIMARY KEY,
    user_id          UUID          NOT NULL,
    centre_test_id   UUID          NOT NULL,
    -- centre_id and test_id are copied from centre_tests on purpose: reports and
    -- listings need the centre and the test without joining through the price
    -- row, and the booking must stay readable even if centre_tests is edited.
    centre_id        UUID          NOT NULL,
    test_id          UUID          NOT NULL,
    appointment_time TIMESTAMPTZ   NOT NULL,

    -- Price snapshot. See the note at the bottom of this file.
    amount           NUMERIC(10, 2) NOT NULL,

    status           VARCHAR(20)   NOT NULL DEFAULT 'PENDING',
    created_at       TIMESTAMPTZ   NOT NULL DEFAULT now(),
    updated_at       TIMESTAMPTZ   NOT NULL DEFAULT now(),

    -- Optimistic locking. Every update does "UPDATE ... WHERE id = ? AND version = ?"
    -- and Hibernate bumps the column, so two concurrent payments cannot both win.
    version          BIGINT        NOT NULL DEFAULT 0,

    CONSTRAINT fk_bookings_user
        FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE RESTRICT,
    CONSTRAINT fk_bookings_centre_test
        FOREIGN KEY (centre_test_id) REFERENCES centre_tests (id) ON DELETE RESTRICT,
    CONSTRAINT fk_bookings_centre
        FOREIGN KEY (centre_id) REFERENCES diagnostic_centres (id) ON DELETE RESTRICT,
    CONSTRAINT fk_bookings_test
        FOREIGN KEY (test_id) REFERENCES diagnostic_tests (id) ON DELETE RESTRICT,

    CONSTRAINT ck_bookings_status
        CHECK (status IN ('PENDING', 'CONFIRMED', 'FAILED', 'CANCELLED')),
    CONSTRAINT ck_bookings_amount_positive CHECK (amount > 0)

    -- No CHECK on appointment_time: a CHECK constraint must be IMMUTABLE and
    -- now() is not, so Postgres rejects "CHECK (appointment_time > now())".
    -- "Must be in the future" is therefore a service-layer rule.
);

-- "GET /bookings" always starts from the logged-in user.
CREATE INDEX idx_bookings_user_id ON bookings (user_id);

-- "GET /bookings?status=CONFIRMED" filters on status.
CREATE INDEX idx_bookings_status ON bookings (status);

-- ---------------------------------------------------------------------------
-- payments
-- ---------------------------------------------------------------------------
CREATE TABLE payments (
    id                 UUID          PRIMARY KEY,
    booking_id         UUID          NOT NULL,
    amount             NUMERIC(10, 2) NOT NULL,
    status             VARCHAR(20)   NOT NULL,
    -- Our stand-in for the payment provider's transaction id. UNIQUE so the
    -- same gateway transaction can never be stored as two payments.
    provider_reference VARCHAR(100) NOT NULL,
    failure_reason     VARCHAR(255),
    created_at         TIMESTAMPTZ   NOT NULL DEFAULT now(),
    updated_at         TIMESTAMPTZ   NOT NULL DEFAULT now(),

    CONSTRAINT fk_payments_booking
        FOREIGN KEY (booking_id) REFERENCES bookings (id) ON DELETE RESTRICT,

    CONSTRAINT uq_payments_provider_reference UNIQUE (provider_reference),

    CONSTRAINT ck_payments_status CHECK (status IN ('SUCCESS', 'FAILED')),
    CONSTRAINT ck_payments_amount_positive CHECK (amount > 0)
);

-- "has this booking already been paid?" and "list the payments of a booking".
CREATE INDEX idx_payments_booking_id ON payments (booking_id);

-- ---------------------------------------------------------------------------
-- webhook_events  (the idempotency ledger)
--
-- event_id carries a UNIQUE constraint and that constraint - not a
-- "SELECT ... WHERE event_id = ?" check - is what makes the webhook safe: if
-- two identical webhooks arrive at the same moment, only one INSERT can win and
-- the loser gets a constraint violation and reports ALREADY_PROCESSED.
--
-- payment_id and booking_id are deliberately NOT foreign keys. A webhook can
-- legally arrive for a payment we have never seen, and we must still be able to
-- record the event with result PAYMENT_NOT_FOUND for auditing. A foreign key
-- would make that insert fail.
-- ---------------------------------------------------------------------------
CREATE TABLE webhook_events (
    id                UUID         PRIMARY KEY,
    event_id          VARCHAR(120) NOT NULL,
    payment_id        UUID         NOT NULL,
    booking_id        UUID         NOT NULL,
    -- Kept for auditing: what exactly did the provider send us? TEXT because a
    -- raw provider payload has no sensible upper bound and we never query it.
    payload           TEXT         NOT NULL,
    status_received   VARCHAR(20)  NOT NULL,
    processed_at      TIMESTAMPTZ,
    -- ALREADY_PROCESSED / PROCESSED / PAYMENT_NOT_FOUND /
    -- IGNORED_INVALID_TRANSITION / SUCCESS_ON_CANCELLED_BOOKING / ...
    processing_result VARCHAR(60),
    created_at        TIMESTAMPTZ  NOT NULL DEFAULT now(),

    CONSTRAINT uq_webhook_events_event_id UNIQUE (event_id),

    CONSTRAINT ck_webhook_events_status_received CHECK (status_received IN ('SUCCESS', 'FAILED'))
);

-- ===========================================================================
--  Why amount is copied into bookings (the price snapshot)
--
--  centre_tests.price changes over time - a centre raises the price of an MRI
--  from 4500.00 to 5200.00. A booking is a commercial agreement made at a
--  specific moment, so it must keep the price the customer actually agreed to.
--
--  If bookings read the price through a join to centre_tests, every old booking
--  would silently change value when the catalogue is updated: the customer
--  could be charged more for a test they booked yesterday, and any historical
--  invoice or refund amount would be impossible to reproduce.
--
--  So the price is copied into bookings.amount at creation time and the booking
--  always reads its own stored amount. The join to centre_tests is only used to
--  find out what the price was at the moment of booking. This is a classic
--  denormalisation done on purpose, and the cost is accepted knowingly: if a
--  price change should apply to existing bookings, that is a separate business
--  decision, not something a schema should do silently.
-- ===========================================================================